api.look('agent');
const cx = api.w/2, cy = 340;
const k = api.seg(t, 0, 1.6);
api.ellipse(cx, cy, 120, 85, {c:'fg', w:4, fill:'accent', a:1, k});
api.circle(cx+105, cy-60, 32, {c:'fg', w:4, fill:'accent', k:api.seg(t,0.4,1.2)});
api.path('M-60 60 L-80 100', {x:cx, y:cy, c:'fg', w:5, k:api.seg(t,0.8,1.5)});
api.path('M40 70 L50 110', {x:cx, y:cy, c:'fg', w:5, k:api.seg(t,0.8,1.5)});
api.shape('flask', cx-90, cy-120, 44, {c:'a2', k:api.seg(t,1.2,2)});
api.kinetic('Lemon garlic chicken', cx, 560, {mode:'rise', k:api.seg(t,1.4,2.8), size:34});
api.say('Roast a lemon garlic chicken', 0.3, 3.3);

api.look('agent');
const cx = api.w/2, cy = 330;
api.ellipse(cx, cy, 120, 85, {c:'fg', w:4, fill:'accent'});
api.circle(cx+105, cy-60, 32, {c:'fg', w:4, fill:'accent'});
const items = [
  {n:'Pat dry', x:cx-110, y:cy-150, c:'a2'},
  {n:'Salt', x:cx+10, y:cy-170, c:'a3'},
  {n:'Lemon', x:cx-130, y:cy+170, c:'warn'},
  {n:'Garlic', x:cx+90, y:cy+170, c:'fg'}
];
items.forEach((it,i)=>{
  const k = api.stag(t, i, {gap:1, dur:0.8, from:0.2});
  api.circle(it.x, it.y, 34*api.ease(k), {c:it.c, w:4, fill:it.c, a:0.35});
  api.arrow(it.x, it.y+(it.y<cy?34:-34), cx+(it.x-cx)*0.4, cy+(it.y<cy?-60:60), {k, c:'fg'});
  api.text(it.n, it.x, it.y+(it.y<cy?-50:56), {size:20, align:'center', weight:'bold', k});
});
api.say('Dry it, salt it, stuff it', 0.3, 4.6);

api.look('agent');
const cx = api.w/2, cy = 300;
api.rect(cx-150, cy-130, 300, 260, {r:24, c:'fg', w:5});
api.rect(cx-120, cy-95, 240, 190, {r:12, c:'fg', w:3, fill:'panel'});
api.ellipse(cx, cy+25, 80, 50, {c:'fg', w:3, fill:'accent'});
api.circle(cx+70, cy-5, 20, {c:'fg', w:3, fill:'accent'});
api.glow(cx, cy+20, 120*(0.8+0.2*api.pulse(t,1)), {c:'accent'});
api.counter(425, cx, 540, {k:api.seg(t,0.3,2), suf:'°F', size:56});
api.text('oven', cx, 575, {size:20, align:'center', c:'dim'});
api.swarm(30, t, {mode:'rise', cx, cy:cy-60, rx:70, ry:60, c:'warn', glow:true});
api.shape('flame', cx, cy+170, 1, {});
api.say('Hot oven, 425 degrees', 0.3, 5.5);

api.look('agent');
const cx = api.w/2;
api.timeline([
  {t:'0', s:'Into oven'},
  {t:'30', s:'Baste'},
  {t:'60', s:'Turn pan'},
  {t:'75', s:'165°F'}
], 90, 150, 240, {k:api.seg(t,0,3.5), vert:true, len:420});
const m = api.seg(t, 3.5, 6);
api.shape('lemon' in {} ? 'lemon' : 'sun', cx+100, 560-420*m, 40, {c:'warn', k:1});
api.text('minutes', cx+90, 130, {size:18, c:'dim'});
api.progress(60, 680, api.w-120, 18, api.ease(api.seg(t,0.5,6)), {k:1});
api.say('About 75 minutes in all', 0.3, 6.5);

api.look('agent');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1);
api.ellipse(cx, cy, 130, 92, {c:'fg', w:4, fill:'warn', k});
api.circle(cx+112, cy-65, 34, {c:'fg', w:4, fill:'warn', k});
api.glow(cx, cy, 170, {c:'warn'});
const h = api.ease(api.seg(t,1,3));
api.rect(cx-90, 520, 180, 36, {r:18, c:'fg', w:3});
api.progress(cx-90, 520, 180, 36, 1, {k:h, c:'good'});
api.shape('check', cx, 600, 50, {c:'good', w:6, k:api.seg(t,2.5,3.5)});
api.text('165°F at the thigh', cx, 480, {size:24, align:'center', weight:'bold', k:api.seg(t,1.5,2.5)});
api.callout('Rest 10 min', cx+60, cy+60, cx+90, cy+190, {k:api.seg(t,3.5,4.5)});
api.say('Rest ten minutes, then carve', 0.3, 5.5);
